const items = $input.all();

// Si no viene nada o el array está vacío
if (items.length === 0 || !items[0].json || Object.keys(items[0].json).length === 0) {
  return [{ json: { status: "SIN_BONOS" } }];
}

// Extraemos todos los vouchers
const vouchers = items.map(i => i.json);

// Filtramos los que tienen VoucherAvailable distinto de "0"
const disponibles = vouchers.filter(v =>
  v.VoucherAvailable !== "0" &&
  v.VoucherAvailable !== 0);

// Si ninguno tiene saldo
if (disponibles.length === 0) {
  return [{ json: { status: "SIN_BONOS" } }];
}

return [{ json: { status: "HAY_BONOS", bonos: disponibles } }];

const items = $input.all();

// Si no viene nada o viene vacío
if (items.length === 0 || !items[0].json || Object.keys(items[0].json).length === 0
    || items[0].json["Cmd24.Clients"] === "") {
  return [{ json: { status: "SIN CLIENTE" } }];
}

const data = items[0].json;

// Si viene con claves numéricas ("0", "1", ...) → coger solo el primero
if (data["0"] && typeof data["0"] === "object") {
  return [{ json: { status: "CLIENTE ENCONTRADO", ...data["0"] } }];
}

// Si viene plano (un solo registro directo)
return [{ json: { status: "CLIENTE ENCONTRADO", ...data } }];

const input = $input.first().json;

if (!input.bonos || input.bonos.length === 0) {
  return [{ json: { data: "" } }];
}

const bonos = input.bonos;
const vistos = {};

for (const b of bonos) {
  const nombre = b.VoucherGroupName || b.VoucherName;
  if (!vistos[nombre]) {
    vistos[nombre] = nombre + ', te quedan disponibles ' + b.VoucherAvailable + ' sesión/es';
  }
}

const lineas = Object.values(vistos);

return [{ json: { data: lineas.join('\n') } }];

